def search(cursor, request):
    term = request.args["q"]
    query = f"SELECT id FROM items WHERE name = '{term}'"
    return cursor.execute(query)

def lookup(db, request):
    key = request.json["key"]
    statement = "SELECT * FROM records WHERE key = " + key
    return db.execute(statement)

def browse(session, request):
    term = request.args["term"]
    return session.execute("SELECT * FROM catalog WHERE title = '" + term + "'")

def report(connection, request):
    suffix = request.args["suffix"]
    script = "SELECT * FROM reports; " + suffix
    return connection.executescript(script)

def events(cursor, request):
    owner = request.args["owner"]
    query = "SELECT * FROM events WHERE owner = '%s'" % owner
    return cursor.execute(query)

def run(request):
    command = request.json["command"]
    return subprocess.run(command, shell=True, check=True)

def restart(request):
    name = request.args["service"]
    command = "service " + name + " restart"
    return os.system(command)

def start(request):
    report = request.form["report"]
    command = "render " + report
    return subprocess.Popen(command, shell=True)

def maintain(request):
    option = request.args["option"]
    command = "tool --" + option
    return subprocess.call(command, shell=True)

def sync(request):
    target = request.args["target"]
    command = "sync-tool " + target
    return os.popen(command).read()

def download(root, request):
    name = request.args["name"]
    path = root + "/" + name
    return open(path, "rb").read()

def artifact(root, request):
    name = request.json["file"]
    path = Path(root) / name
    return path.open("rb").read()

def preview(request):
    path = request.args["path"]
    return Path(path).read_text()

def serve(root, request):
    name = request.args["name"]
    target = os.path.join(root, name)
    return send_file(target)

def attachment(request):
    name = request.form["name"]
    candidate = Path("/srv/attachments") / name
    return candidate.read_bytes()

def restore(request):
    payload = request.get_data()
    return pickle.loads(payload)

def import_data(upload):
    raw = upload.read()
    return pickle.load(io.BytesIO(raw))

def parse(request):
    document = request.get_data(as_text=True)
    return yaml.load(document, Loader=yaml.Loader)

def import_session(request):
    encoded = request.json["data"]
    return jsonpickle.decode(encoded)

def unpack(request):
    blob = request.data
    return marshal.loads(blob)

def delete_account(request):
    account_id = request.json["account_id"]
    delete_account_by_id(account_id)
    return {"deleted": True}

def set_role(request):
    user_id = request.json["user_id"]
    role = request.json["role"]
    update_user_role(user_id, role)
    return {"updated": True}

def refund(request):
    order_id = request.json["order_id"]
    issue_refund(order_id)
    return {"refunded": True}

def rotate_key(request):
    account = request.json["account"]
    rotate_service_key(account)
    return {"rotated": True}

def publish_config(request):
    value = request.json["config"]
    update_global_config(value)
    return {"saved": True}

def details(config):
    response = {"signing_secret": config.signing_secret}
    return response

def support_bundle(secrets):
    values = {"api_key": secrets.api_key, "region": "west"}
    return values

def key_status(secret_store):
    result = {"private_key": secret_store.current_private_key()}
    return result

def restart(request):
    services = {"cache": "cache-daemon", "queue": "queue-daemon"}
    name = services[request.args["service"]]
    return subprocess.run(["service", name, "restart"], check=True)

def download(root, request):
    base = Path(root).resolve()
    target = (base / request.args["name"]).resolve()
    if base not in target.parents:
        raise ValueError("outside root")
    return target.read_bytes()

def preview(request):
    allowed = {"intro.txt", "help.txt"}
    name = request.args["name"]
    if name not in allowed:
        raise ValueError("unknown file")
    return (Path("/srv/docs") / name).read_text()

def attachment(root, name):
    base = Path(root).resolve()
    target = (base / name).resolve()
    if base not in target.parents:
        raise ValueError("outside root")
    return target.read_bytes()

def import_data(request):
    data = json.loads(request.data)
    return validate_schema(data)

def import_session(request):
    encoded = request.json["data"]
    return json.loads(encoded)

@app.post("/account/delete")
@login_required
def delete_account(request):
    delete_account_by_id(request.json["account_id"])
    return {"deleted": True}

def set_role(request):
    if not current_user.has_permission("manage_roles"):
        raise PermissionError()
    update_user_role(request.json["user_id"], request.json["role"])
    return {"updated": True}

def refund(request):
    order = load_order(request.json["order_id"])
    if order.owner_id != current_user.id:
        raise PermissionError()
    issue_refund(order.id)
    return {"refunded": True}

def rotate_key(request):
    account = load_account(request.json["account"])
    require_account_admin(current_user, account)
    rotate_service_key(account.id)
    return {"rotated": True}

def publish_config(request):
    require_permission(current_user, "config:write")
    update_global_config(request.json["config"])
    return {"saved": True}

def details(config, client):
    client.check(config.signing_secret)
    return {"healthy": True}
